create or replace function public.app_7700_expenses_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.app_7700_is_admin() then return new; end if;
  if tg_op = 'INSERT' then
    new.customer_id := auth.uid();
  else
    new.customer_id := old.customer_id;
  end if;
  return new;
end $$;
