create or replace function public.app_7700_stats() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.app_7700_is_admin() then raise exception 'admins only'; end if;
  return jsonb_build_object('expenses', (select count(*) from public.app_7700_expenses), '_customers', (select count(*) from public.app_7700_profiles where role = 'customer'));
end $$;
grant execute on function public.app_7700_stats() to authenticated;

